// ====== CONFIG / 配置 ======
const BASE_BALANCE = 5.00;   // 你在 BASE_DATE 那天看到的 OpenAI 余额 (USD)
// BASE_DATE 在 "Get Costs" 节点的 start_time 里改
const RATE = { textIn: 5, imageIn: 8, imageOut: 30 }; // USD per 1M tokens
// ===========================

const img = $('Generate Image').first().json;
const r = Array.isArray(img) ? img[0] : img;
const u = r.usage || {};
const inD = u.input_tokens_details || {};
const outD = u.output_tokens_details || {};
const textIn = inD.text_tokens ?? u.input_tokens ?? 0;
const imageIn = inD.image_tokens ?? 0;
const imageOut = outD.image_tokens ?? u.output_tokens ?? 0;
const cost = (textIn * RATE.textIn + imageIn * RATE.imageIn + imageOut * RATE.imageOut) / 1e6;

let spent = null;
try {
  const c = $('Get Costs').first().json;
  if (c && Array.isArray(c.data)) {
    spent = 0;
    for (const b of c.data) for (const x of (b.results || [])) spent += Number((x.amount && x.amount.value) || 0);
  }
} catch (e) {}

const f = (n) => '$' + n.toFixed(4);
const lines = [];
lines.push('本次用量：输入 ' + (u.input_tokens || 0) + ' + 输出 ' + (u.output_tokens || 0) + ' = ' + (u.total_tokens || 0) + ' token');
lines.push('本次花费：约 ' + f(cost));
if (spent !== null) {
  lines.push('基准日起累计花费：' + f(spent) + '（官方统计，可能有延迟）');
  lines.push('估算剩余余额：约 ' + f(BASE_BALANCE - spent));
} else {
  lines.push('累计花费和剩余余额：查询失败（检查 Admin key 凭据）');
}
const first = r.data && r.data[0] ? r.data[0] : {};
return [{ json: { usage_summary: lines.join('\n'), size: r.size, quality: r.quality, b64_json: first.b64_json } }];
